mapper.select:
SELECT br.id AS id, br.book_id AS bookId, bk.title AS bookTitle, bk.author AS bookAuthor, br.reader_id AS readerId, rd.name AS readerName, rd.card_no AS readerCardNo, br.borrow_date AS borrowDate, br.due_date AS dueDate, br.return_date AS returnDate, br.status AS status FROM borrow br JOIN book bk ON br.book_id = bk.id JOIN reader rd ON br.reader_id = rd.id
AND br.status = #{status} AND br.reader_id = #{readerId}
ORDER BY br.id DESC
